.nudge-sim-container {
    padding: 24px;
    background: radial-gradient(ellipse at top, #1a1240 0%, #0a0823 40%, #050414 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6e9f5;
}
.nudge-sim-header {
    background: linear-gradient(135deg, rgba(99,102,241,0.18), rgba(245,158,11,0.12));
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 20px;
    padding: 28px 32px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.nudge-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #6366f1, #f59e0b, #6366f1);
}
.nudge-sim-badge {
    display: inline-block;
    padding: 4px 12px;
    background: rgba(99,102,241,0.25);
    border: 1px solid rgba(99,102,241,0.4);
    border-radius: 999px;
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #c7d2fe;
    margin-bottom: 12px;
}
.nudge-sim-header h1 {
    font-size: 2rem;
    font-weight: 800;
    margin: 0;
    background: linear-gradient(135deg, #a5b4fc 0%, #fbbf24 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: -0.01em;
}
.nudge-sim-subtitle {
    color: #a5b4fc;
    font-size: 0.95rem;
    margin-top: 6px;
    font-weight: 500;
}
.nudge-sim-period-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}
.nudge-sim-period-counter {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.12);
    padding: 10px 18px;
    border-radius: 12px;
    font-size: 0.95rem;
    color: #cbd5e1;
    font-weight: 600;
}
.nudge-sim-period-counter span {
    margin: 0 3px;
}
.nudge-sim-mode {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 18px;
    background: rgba(59,130,246,0.18);
    border: 1px solid rgba(59,130,246,0.4);
    border-radius: 12px;
    color: #93c5fd;
    font-weight: 700;
    font-size: 0.85rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    transition: all 0.3s ease;
}
.nudge-sim-mode.architect-mode {
    background: rgba(245,158,11,0.18);
    border-color: rgba(245,158,11,0.45);
    color: #fcd34d;
}
.nudge-sim-mode-dot {
    width: 9px;
    height: 9px;
    background: currentColor;
    border-radius: 50%;
    box-shadow: 0 0 10px currentColor;
    animation: nudgePulse 2s ease-in-out infinite;
}
@keyframes nudgePulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(1.2); }
}
.nudge-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.nudge-sim-kpi-card {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 18px 16px;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, background 0.25s ease;
}
.nudge-sim-kpi-card:hover {
    transform: translateY(-3px);
    background: rgba(255,255,255,0.08);
}
.nudge-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 3px;
    height: 100%;
}
.nudge-sim-kpi-effective::before { background: linear-gradient(180deg, #f59e0b, #ef4444); }
.nudge-sim-kpi-freedom::before { background: linear-gradient(180deg, #10b981, #3b82f6); }
.nudge-sim-kpi-biases::before { background: linear-gradient(180deg, #a78bfa, #ec4899); }
.nudge-sim-kpi-targets::before { background: linear-gradient(180deg, #fbbf24, #f97316); }
.nudge-sim-kpi-label {
    color: #94a3b8;
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.nudge-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 800;
    color: #ffffff;
    letter-spacing: -0.02em;
}
.nudge-sim-kpi-effective .nudge-sim-kpi-value { color: #fbbf24; }
.nudge-sim-kpi-freedom .nudge-sim-kpi-value { color: #34d399; }
.nudge-sim-kpi-biases .nudge-sim-kpi-value { color: #c4b5fd; }
.nudge-sim-kpi-targets .nudge-sim-kpi-value { color: #fb923c; }
.nudge-sim-freedom-bar {
    margin-top: 10px;
    height: 6px;
    background: rgba(255,255,255,0.08);
    border-radius: 3px;
    overflow: hidden;
}
.nudge-sim-freedom-fill {
    height: 100%;
    background: linear-gradient(90deg, #10b981, #34d399);
    width: 100%;
    transition: width 0.6s ease, background 0.6s ease;
    border-radius: 3px;
}
.nudge-sim-briefing {
    background: rgba(255,255,255,0.04);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 18px;
    padding: 22px;
    margin-bottom: 22px;
}
.nudge-sim-briefing-title {
    font-size: 1.1rem;
    font-weight: 700;
    color: #fbbf24;
    margin-bottom: 16px;
    letter-spacing: 0.02em;
}
.nudge-sim-consumer-box,
.nudge-sim-reveal-box,
.nudge-sim-scenario-box {
    padding: 14px 16px;
    border-radius: 12px;
    margin-bottom: 12px;
}
.nudge-sim-consumer-box {
    background: rgba(59,130,246,0.1);
    border-left: 3px solid #3b82f6;
}
.nudge-sim-reveal-box {
    background: rgba(236,72,153,0.1);
    border-left: 3px solid #ec4899;
}
.nudge-sim-scenario-box {
    background: rgba(245,158,11,0.1);
    border-left: 3px solid #f59e0b;
    margin-bottom: 0;
}
.nudge-sim-consumer-header,
.nudge-sim-reveal-header,
.nudge-sim-scenario-header {
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 6px;
}
.nudge-sim-consumer-header { color: #93c5fd; }
.nudge-sim-reveal-header { color: #f9a8d4; }
.nudge-sim-scenario-header { color: #fcd34d; }
.nudge-sim-consumer-text,
.nudge-sim-reveal-text,
.nudge-sim-scenario-text {
    color: #e6e9f5;
    font-size: 0.92rem;
    line-height: 1.55;
}
.nudge-sim-controls {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 18px;
    padding: 22px;
    margin-bottom: 24px;
}
.nudge-sim-controls h3 {
    color: #fbbf24;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 16px;
    letter-spacing: 0.02em;
}
.nudge-sim-control-row {
    margin-bottom: 14px;
}
.nudge-sim-control-row label {
    display: block;
    color: #cbd5e1;
    font-size: 0.85rem;
    font-weight: 600;
    margin-bottom: 6px;
}
.nudge-sim-controls select {
    width: 100%;
    background: rgba(10,8,35,0.85);
    border: 1px solid rgba(255,255,255,0.18);
    color: #ffffff;
    border-radius: 10px;
    padding: 10px 12px;
    font-size: 0.92rem;
    font-weight: 500;
    transition: border-color 0.2s ease;
}
.nudge-sim-controls select:focus {
    outline: none;
    border-color: #fbbf24;
    box-shadow: 0 0 0 3px rgba(251,191,36,0.18);
}
.nudge-sim-controls select option {
    background: #1a1240;
    color: #ffffff;
    padding: 8px;
}
.nudge-sim-hint-small {
    color: #8b93b0;
    font-size: 0.78rem;
    margin-top: 5px;
    font-style: italic;
}
.nudge-sim-button-row {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-top: 18px;
}
.nudge-sim-controls .btn-primary {
    background: linear-gradient(135deg, #f59e0b, #ef4444);
    border: none;
    color: #ffffff;
    padding: 12px 28px;
    border-radius: 10px;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    box-shadow: 0 6px 18px rgba(245,158,11,0.35);
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.nudge-sim-controls .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 24px rgba(245,158,11,0.45);
    background: linear-gradient(135deg, #f59e0b, #ef4444);
}
.nudge-sim-controls .btn-outline-secondary {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.2);
    color: #cbd5e1;
    padding: 10px 18px;
    border-radius: 10px;
    font-weight: 500;
}
.nudge-sim-controls .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.08);
    color: #ffffff;
}
.nudge-sim-chart-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.nudge-sim-chart-card {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 18px;
}
.nudge-sim-chart-card h4 {
    color: #c7d2fe;
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin: 0 0 14px;
}
.nudge-sim-chart-wrap {
    position: relative;
    height: 220px;
}
.nudge-sim-history {
    background: rgba(255,255,255,0.04);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 18px;
    overflow-x: auto;
}
.nudge-sim-history h4 {
    color: #c7d2fe;
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin: 0 0 14px;
}
.nudge-sim-container #usfHistoryTable {
    width: 100%;
    color: #e6e9f5;
    background: transparent;
    margin: 0;
}
.nudge-sim-container #usfHistoryTable thead th {
    background: rgba(99,102,241,0.15);
    color: #a5b4fc;
    border: none;
    padding: 10px 12px;
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    font-weight: 700;
}
.nudge-sim-container #usfHistoryTable tbody td {
    background: transparent;
    border-color: rgba(255,255,255,0.08);
    color: #e6e9f5;
    padding: 10px 12px;
    font-size: 0.88rem;
}
.nudge-sim-container #usfHistoryTable tbody tr:hover td {
    background: rgba(99,102,241,0.08);
}
.nudge-sim-reveal-flash {
    animation: nudgeFlash 0.8s ease;
}
@keyframes nudgeFlash {
    0% { background: rgba(236,72,153,0.4); }
    100% { background: rgba(236,72,153,0.1); }
}
@media (max-width: 768px) {
    .nudge-sim-container { padding: 14px; }
    .nudge-sim-header { padding: 20px; }
    .nudge-sim-header h1 { font-size: 1.6rem; }
    .nudge-sim-kpi-value { font-size: 1.5rem; }
    .nudge-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .nudge-sim-period-row { flex-direction: column; align-items: stretch; }
    .nudge-sim-controls .btn-primary { width: 100%; }
}
/* v1.1.0 — completion debrief modal */
.nudge-sim-complete { text-align: center; padding: 8px 4px; color: #e6e9f5; }
.nudge-sim-complete-stars { font-size: 2rem; letter-spacing: 6px; }
.nudge-sim-complete-title { margin: 8px 0 2px; font-size: 1.05rem; color: #94a3b8; text-transform: uppercase; letter-spacing: 1px; }
.nudge-sim-complete-score { font-size: 2.6rem; font-weight: 700; color: #fbbf24; line-height: 1.1; }
.nudge-sim-complete-score .nsc-max { font-size: 1rem; color: #94a3b8; font-weight: 500; }
.nudge-sim-complete-tier { font-size: 1.1rem; margin: 4px 0 14px; color: #c4b5fd; font-weight: 600; }
.nudge-sim-complete-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.nudge-sim-complete-kpi { background: rgba(255,255,255,0.05); border-radius: 10px; padding: 10px 14px; min-width: 92px; }
.nudge-sim-complete-kpi .nsck-val { display: block; font-size: 1.3rem; font-weight: 700; color: #fff; }
.nudge-sim-complete-kpi .nsck-lbl { display: block; font-size: 0.72rem; color: #94a3b8; margin-top: 2px; }
.nudge-sim-complete-insights-wrap { text-align: left; max-width: 540px; margin: 0 auto; }
.nudge-sim-complete-insights-wrap .nsci-head { font-weight: 700; margin-bottom: 6px; }
.nudge-sim-complete-insights { margin: 0 0 4px; padding-left: 20px; }
.nudge-sim-complete-insights li { margin-bottom: 6px; line-height: 1.4; }

