(function() {
    'use strict';

    class NudgeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Choice Architect: Nudge, Bias and the Irrational Consumer';
            this.version = '1.1.0';

            this.BIAS_KEYS = ['default', 'anchoring', 'framing', 'present', 'loss', 'herding'];

            this.ROUNDS = [
                {
                    id: 1,
                    titleKey: 'r1_title',
                    consumerKey: 'r1_consumer',
                    revealKey: 'r1_reveal',
                    scenarioKey: 'r1_scenario',
                    correctBias: 'default',
                    biasChoices: ['default', 'anchoring', 'loss', 'present'],
                    nudgeOptions: [
                        { value: 'opt_in',   labelKey: 'r1_n1', effectiveness: 40, freedomCost: 0  },
                        { value: 'active',   labelKey: 'r1_n2', effectiveness: 65, freedomCost: 5  },
                        { value: 'opt_out',  labelKey: 'r1_n3', effectiveness: 92, freedomCost: 18 },
                        { value: 'escalate', labelKey: 'r1_n4', effectiveness: 88, freedomCost: 12 }
                    ],
                    target: 85
                },
                {
                    id: 2,
                    titleKey: 'r2_title',
                    consumerKey: 'r2_consumer',
                    revealKey: 'r2_reveal',
                    scenarioKey: 'r2_scenario',
                    correctBias: 'anchoring',
                    biasChoices: ['anchoring', 'framing', 'default', 'herding'],
                    nudgeOptions: [
                        { value: 'remove_exp', labelKey: 'r2_n1', effectiveness: 10, freedomCost: 18 },
                        { value: 'add_decoy', labelKey: 'r2_n2', effectiveness: 16, freedomCost: 4  },
                        { value: 'reposition', labelKey: 'r2_n3', effectiveness: 22, freedomCost: 2  },
                        { value: 'chef_pick', labelKey: 'r2_n4', effectiveness: 14, freedomCost: 3  }
                    ],
                    target: 20
                },
                {
                    id: 3,
                    titleKey: 'r3_title',
                    consumerKey: 'r3_consumer',
                    revealKey: 'r3_reveal',
                    scenarioKey: 'r3_scenario',
                    correctBias: 'framing',
                    biasChoices: ['framing', 'herding', 'anchoring', 'loss'],
                    nudgeOptions: [
                        { value: 'abs_kwh',  labelKey: 'r3_n1', effectiveness: 1, freedomCost: 0 },
                        { value: 'cost',     labelKey: 'r3_n2', effectiveness: 2, freedomCost: 0 },
                        { value: 'neighbour',labelKey: 'r3_n3', effectiveness: 4, freedomCost: 3 },
                        { value: 'smiley',   labelKey: 'r3_n4', effectiveness: 5, freedomCost: 2 },
                        { value: 'carbon',   labelKey: 'r3_n5', effectiveness: 3, freedomCost: 1 }
                    ],
                    target: 4
                },
                {
                    id: 4,
                    titleKey: 'r4_title',
                    consumerKey: 'r4_consumer',
                    revealKey: 'r4_reveal',
                    scenarioKey: 'r4_scenario',
                    correctBias: 'default',
                    biasChoices: ['default', 'loss', 'present', 'framing'],
                    nudgeOptions: [
                        { value: 'opt_out_law', labelKey: 'r4_n1', effectiveness: 90, freedomCost: 30 },
                        { value: 'active_mand', labelKey: 'r4_n2', effectiveness: 68, freedomCost: 10 },
                        { value: 'prompted',    labelKey: 'r4_n3', effectiveness: 72, freedomCost: 5  },
                        { value: 'emotional',   labelKey: 'r4_n4', effectiveness: 35, freedomCost: 0  }
                    ],
                    target: 75
                },
                {
                    id: 5,
                    titleKey: 'r5_title',
                    consumerKey: 'r5_consumer',
                    revealKey: 'r5_reveal',
                    scenarioKey: 'r5_scenario',
                    correctBias: 'present',
                    biasChoices: ['present', 'loss', 'anchoring', 'framing'],
                    nudgeOptions: [
                        { value: 'higher_int', labelKey: 'r5_n1', effectiveness: 6,  freedomCost: 0 },
                        { value: 'commit',     labelKey: 'r5_n2', effectiveness: 14, freedomCost: 6 },
                        { value: 'roundup',    labelKey: 'r5_n3', effectiveness: 10, freedomCost: 2 },
                        { value: 'prize',      labelKey: 'r5_n4', effectiveness: 12, freedomCost: 3 },
                        { value: 'smt',        labelKey: 'r5_n5', effectiveness: 18, freedomCost: 5 }
                    ],
                    target: 15
                },
                {
                    id: 6,
                    titleKey: 'r6_title',
                    consumerKey: 'r6_consumer',
                    revealKey: 'r6_reveal',
                    scenarioKey: 'r6_scenario',
                    correctBias: 'framing',
                    biasChoices: ['framing', 'default', 'herding', 'loss'],
                    nudgeOptions: [
                        { value: 'paternal',  labelKey: 'r6_n1', effectiveness: 60, freedomCost: 25 },
                        { value: 'balanced',  labelKey: 'r6_n2', effectiveness: 75, freedomCost: 8  },
                        { value: 'reject',    labelKey: 'r6_n3', effectiveness: 25, freedomCost: 0  },
                        { value: 'transparent',labelKey: 'r6_n4',effectiveness: 70, freedomCost: 4  }
                    ],
                    target: 70
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalEffectiveness: 0,
                    freedomGauge: 100,
                    biasesCorrect: 0,
                    biasesAttempted: 0,
                    targetsHit: 0,
                    effectivenessHistory: [],
                    freedomHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { bias: '', nudge: '' };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var biasEl = document.getElementById('biasSelect');
            var nudgeEl = document.getElementById('nudgeSelect');
            if (biasEl) decisions.bias = biasEl.value;
            if (nudgeEl) decisions.nudge = nudgeEl.value;

            if (!decisions.bias) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('bias_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.nudge) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('nudge_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var nudge = round.nudgeOptions.find(function(n) { return n.value === d.nudge; });
            if (!nudge) nudge = round.nudgeOptions[0];

            var biasCorrect = (d.bias === round.correctBias);
            var diagnosisBonus = biasCorrect ? 1.1 : 0.85;
            var rawEffect = nudge.effectiveness * diagnosisBonus;
            var effectiveness = Math.round(rawEffect * 10) / 10;

            var freedomCost = nudge.freedomCost;
            var prevFreedom = state.domainState.freedomGauge;
            var newFreedom = Math.max(0, prevFreedom - freedomCost);

            var targetHit = effectiveness >= round.target;

            state.domainState.totalEffectiveness += effectiveness;
            state.domainState.freedomGauge = newFreedom;
            state.domainState.biasesAttempted += 1;
            if (biasCorrect) state.domainState.biasesCorrect += 1;
            if (targetHit) state.domainState.targetsHit += 1;

            state.domainState.effectivenessHistory.push(effectiveness);
            state.domainState.freedomHistory.push(newFreedom);

            // --- v1.1.0: persist a gradable, normalized 0-100 score so the
            // reporting layer (results_utils.php → domainState.performance.overallScore)
            // records a real score/timeline for every period. ---
            var sg = this._computeScore(state.domainState);
            state.domainState.score = sg.overallScore;
            state.domainState.performance = { overallScore: sg.overallScore, grade: sg.grade, stars: sg.stars };

            var biasesDisp = state.domainState.biasesCorrect + ' / ' + state.domainState.biasesAttempted;
            var biasesEl = document.getElementById('biasesCountDisplay');
            if (biasesEl) biasesEl.textContent = biasesDisp;
            var barEl = document.getElementById('freedomBar');
            if (barEl) {
                barEl.style.width = newFreedom + '%';
                if (newFreedom > 60) {
                    barEl.style.background = 'linear-gradient(90deg, #10b981, #34d399)';
                } else if (newFreedom > 30) {
                    barEl.style.background = 'linear-gradient(90deg, #f59e0b, #fbbf24)';
                } else {
                    barEl.style.background = 'linear-gradient(90deg, #ef4444, #f87171)';
                }
            }

            var revealBox = document.querySelector('.nudge-sim-reveal-box');
            if (revealBox) {
                revealBox.classList.remove('nudge-sim-reveal-flash');
                void revealBox.offsetWidth;
                revealBox.classList.add('nudge-sim-reveal-flash');
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: (state.currentPeriod || 1) + 1 });
            }, 400);

            return {
                period: state.currentPeriod,
                bias: d.bias,
                biasCorrect: biasCorrect,
                nudge: d.nudge,
                effectiveness: effectiveness,
                freedom: newFreedom,
