        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalEffect = history.reduce(function(s, r) { return s + (r.results && r.results.effectiveness ? r.results.effectiveness : 0); }, 0);
            var avgEffect = totalEffect / history.length;
            var targetsHit = history.filter(function(r) { return r.results && r.results.targetHit; }).length;
            var correct = history.filter(function(r) { return r.results && r.results.biasCorrect; }).length;
            var finalFreedom = history.length ? (history[history.length - 1].results.freedom || 0) : 100;

            var stars = 1;
            if (correct >= 4 && targetsHit >= 4) stars = 2;
            if (correct >= 5 && targetsHit >= 5 && finalFreedom >= 50) stars = 3;

            var performance = 'Intern';
            if (stars === 2) performance = 'Behavioural Economist';
            if (stars === 3) performance = 'Choice Architect';

            var insights = [];
            if (correct < 4) insights.push(window.mySimulation.t('insight_diagnose_more'));
            if (finalFreedom < 40) insights.push(window.mySimulation.t('insight_freedom_low'));
            if (targetsHit >= 5) insights.push(window.mySimulation.t('insight_strong_nudges'));
            if (stars === 3) insights.push(window.mySimulation.t('insight_libertarian_paternalism'));
            if (!insights.length) insights.push(window.mySimulation.t('insight_keep_balance'));

            var overallScore = Math.round(100 * (correct + targetsHit) / (2 * this.ROUNDS.length));

            return {
                totalEffect: Math.round(totalEffect * 10) / 10,
                avgEffect: Math.round(avgEffect * 10) / 10,
                targetsHit: targetsHit,
                biasesCorrect: correct,
                finalFreedom: Math.round(finalFreedom),
                stars: stars,
                overallScore: overallScore,
                performance: performance,
                totalPeriods: history.length,
                insights: insights
            };
        }

