        _updateBriefing(state) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var period = state.currentPeriod || 1;
            var finished = period > this.ROUNDS.length;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) {
                titleEl.textContent = t('round_word') + ' ' + round.id + ' · ' + t(round.titleKey);
            }

            var consumerEl = document.getElementById('consumerText');
            if (consumerEl) consumerEl.innerHTML = t(round.consumerKey);

            var revealEl = document.getElementById('revealText');
            if (revealEl) revealEl.innerHTML = t(round.revealKey);

            var scenarioEl = document.getElementById('scenarioText');
            if (scenarioEl) scenarioEl.innerHTML = t(round.scenarioKey);

            var modeEl = document.getElementById('modeIndicator');
            var modeLabel = document.getElementById('modeLabel');
            if (modeEl && modeLabel) {
                modeEl.classList.add('architect-mode');
                modeLabel.textContent = t('mode_architect');
            }

            var biasSelect = document.getElementById('biasSelect');
            if (biasSelect) {
                biasSelect.innerHTML = '';
                var placeholder = document.createElement('option');
                placeholder.value = '';
                placeholder.textContent = t('select_bias');
                biasSelect.appendChild(placeholder);
                round.biasChoices.forEach(function(b) {
                    var opt = document.createElement('option');
                    opt.value = b;
                    opt.textContent = t('bias_' + b);
                    biasSelect.appendChild(opt);
                });
            }

            var nudgeSelect = document.getElementById('nudgeSelect');
            if (nudgeSelect) {
                nudgeSelect.innerHTML = '';
                var placeholder2 = document.createElement('option');
                placeholder2.value = '';
                placeholder2.textContent = t('select_nudge');
                nudgeSelect.appendChild(placeholder2);
                round.nudgeOptions.forEach(function(n) {
                    var opt = document.createElement('option');
                    opt.value = n.value;
                    opt.textContent = t(n.labelKey);
                    nudgeSelect.appendChild(opt);
                });
            }

            if (finished) {
                var controlsEl = document.querySelector('.nudge-sim-controls');
                if (controlsEl) controlsEl.style.opacity = '0.5';
            }
        }

        _computeScore(ds) {
            var maxR = this.ROUNDS.length;
            var correct = ds.biasesCorrect || 0;
            var hits = ds.targetsHit || 0;
            var overallScore = Math.round(100 * (correct + hits) / (2 * maxR));
            var freedom = (typeof ds.freedomGauge === 'number') ? ds.freedomGauge : 100;
            var stars = 1;
            if (correct >= 4 && hits >= 4) stars = 2;
            if (correct >= 5 && hits >= 5 && freedom >= 50) stars = 3;
            var grade = stars === 3 ? 'Choice Architect' : (stars === 2 ? 'Behavioural Economist' : 'Behavioural Intern');
            return { overallScore: overallScore, stars: stars, grade: grade };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var s = summary || {};
            var stars = s.stars || 1;
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var starRow = '';
            for (var i = 0; i < 3; i++) { starRow += (i < stars ? '⭐' : '☆'); }
            var tierKey = stars === 3 ? 'perf_architect' : (stars === 2 ? 'perf_economist' : 'perf_intern');
            var finalFreedom = (typeof s.finalFreedom === 'number') ? s.finalFreedom : 100;
            var insightsHtml = '';
            if (s.insights && s.insights.length) {
                insightsHtml = '<ul class="nudge-sim-complete-insights">';
                s.insights.forEach(function(ins) { insightsHtml += '<li>' + ins + '</li>'; });
                insightsHtml += '</ul>';
            }
            var kpi = function(val, label) {
                return '<div class="nudge-sim-complete-kpi"><span class="nsck-val">' + val + '</span><span class="nsck-lbl">' + label + '</span></div>';
            };
            var html = ''
                + '<div class="nudge-sim-complete">'
                +   '<div class="nudge-sim-complete-stars">' + starRow + '</div>'
                +   '<div class="nudge-sim-complete-title">' + t('complete_title') + '</div>'
                +   '<div class="nudge-sim-complete-score">' + score + '<span class="nsc-max">/100</span></div>'
                +   '<div class="nudge-sim-complete-tier">' + t(tierKey) + '</div>'
                +   '<div class="nudge-sim-complete-kpis">'
                +     kpi((s.biasesCorrect || 0) + '/' + (this.ROUNDS.length), t('cm_biases'))
                +     kpi((s.targetsHit || 0) + '/' + (this.ROUNDS.length), t('cm_targets'))
                +     kpi(finalFreedom, t('cm_freedom'))
                +     kpi((s.totalEffect || 0) + '%', t('cm_effect'))
                +   '</div>'
                +   (insightsHtml ? ('<div class="nudge-sim-complete-insights-wrap"><div class="nsci-head">' + t('cm_insights') + '</div>' + insightsHtml + '</div>') : '')
                + '</div>';
            return html;
        }

